package com.emberfall.game.render

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.Path
import com.emberfall.game.content.ContentAssetIds
import com.emberfall.game.content.ContentRepository
import com.emberfall.game.world.TileType
import java.util.Random

/**
 * Tile art for the world.
 *
 * Primary path: a bundled 1024x1024 texture atlas (`assets/tileset.png`) with
 * 128x128 material tiles (12 types x 4 variants), generated by
 * `tools/gen_tileset.py`. If the atlas is missing the renderer falls back to
 * the original runtime-painted 32x32 tiles.
 *
 * Either way the renderer sees one bitmap per tile: a screen of terrain is a
 * few hundred cached blits per frame.
 */
class TileAtlas(context: Context) {

    companion object {
        const val TILE_PX = 32
        const val VARIANTS = 4
        const val ATLAS_CELL = 128
        const val ATLAS_COLUMNS = 8
    }

    private val sheets: Array<Array<Bitmap?>> =
        Array(TileType.values().size) { arrayOfNulls<Bitmap>(VARIANTS) }
    private val isoSheets: Array<Array<Bitmap?>> =
        Array(TileType.values().size) { arrayOfNulls<Bitmap>(VARIANTS) }
    private val transitionSheets: Array<MutableMap<Int, Bitmap>> =
        Array(TileType.values().size) { HashMap() }
    private val content = ContentRepository.from(context)

    init {
        val atlas = loadAtlas(context)
        val themed = TileType.values().filter { it.ordinal >= 12 }.associateWith { type ->
            try {
                context.assets.open("terrain/${type.name.lowercase()}.png").use { input ->
                    BitmapFactory.decodeStream(input)?.takeIf { it.width == ATLAS_CELL * VARIANTS && it.height == ATLAS_CELL }
                }
            } catch (_: Exception) { null }
        }
        if (atlas != null) {
            for (type in TileType.values()) {
                for (variant in 0 until VARIANTS) {
                    sheets[type.ordinal][variant] = if (type.ordinal < 12) {
                        val index = type.ordinal * VARIANTS + variant
                        val x = (index % ATLAS_COLUMNS) * ATLAS_CELL
                        val y = (index / ATLAS_COLUMNS) * ATLAS_CELL
                        Bitmap.createBitmap(atlas, x, y, ATLAS_CELL, ATLAS_CELL)
                    } else themed[type]?.let { Bitmap.createBitmap(it, variant * ATLAS_CELL, 0, ATLAS_CELL, ATLAS_CELL) }
                        ?: paintTile(type, variant)
                }
            }
        } else {
            for (type in TileType.values()) {
                for (variant in 0 until VARIANTS) {
                    sheets[type.ordinal][variant] = themed[type]?.let {
                        Bitmap.createBitmap(it, variant * ATLAS_CELL, 0, ATLAS_CELL, ATLAS_CELL)
                    } ?: paintTile(type, variant)
                }
            }
        }
    }

    private fun loadAtlas(context: Context): Bitmap? = content.bitmap(
        ContentAssetIds.TILESET,
        "tileset.png",
    ) { bitmap ->
        bitmap.width >= ATLAS_COLUMNS * ATLAS_CELL &&
            bitmap.height >= ((12 * VARIANTS + ATLAS_COLUMNS - 1) / ATLAS_COLUMNS) * ATLAS_CELL
    }

    fun bitmap(type: TileType, variant: Int): Bitmap =
        sheets[type.ordinal][variant and (VARIANTS - 1)]!!

    fun isoBitmap(type: TileType, variant: Int): Bitmap {
        val slot = variant and (VARIANTS - 1)
        isoSheets[type.ordinal][slot]?.let { return it }
        val source = bitmap(type, slot)
        val result = Bitmap.createBitmap(IsoMath.TILE_WIDTH.toInt(), IsoMath.TILE_HEIGHT.toInt(), Bitmap.Config.ARGB_8888)
        for (y in 0 until result.height) for (x in 0 until result.width) {
            val sx = (x + .5f) / result.width * 2f - 1f
            val sy = (y + .5f) / result.height * 2f - 1f
            val u = (sx + sy + 1f) * .5f
            val v = (sy - sx + 1f) * .5f
            if (u >= 0f && u < 1f && v >= 0f && v < 1f) {
                result.setPixel(x, y, source.getPixel((u * source.width).toInt(), (v * source.height).toInt()))
            }
        }
        isoSheets[type.ordinal][slot] = result
        return result
    }

    fun transitionBitmap(target: TileType, mask: Int): Bitmap {
        val index = IsoAutotile.variant(mask)
        return transitionSheets[target.ordinal].getOrPut(index) {
            IsoAutotile.overlay(isoBitmap(target, 0), IsoAutotile.masks[index])
        }
    }

    private fun paintTile(type: TileType, variant: Int): Bitmap {
        val bitmap = Bitmap.createBitmap(TILE_PX, TILE_PX, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)
        val random = Random((type.id * 7919 + variant * 104729).toLong())
        val paint = Paint().apply {
            isAntiAlias = false
            style = Paint.Style.FILL
        }

        when (type) {
            TileType.GRASS -> {
                canvas.drawColor(jitter(Palette.GRASS, random))
                grassBlades(canvas, paint, random)
            }

            TileType.FOREST_FLOOR -> {
                canvas.drawColor(jitter(Palette.FOREST_FLOOR, random))
                leafLitter(canvas, paint, random)
            }

            TileType.FLOWERS -> {
                canvas.drawColor(jitter(Palette.GRASS, random))
                grassBlades(canvas, paint, random)
                flowers(canvas, paint, random)
            }

            TileType.DIRT -> {
                canvas.drawColor(jitter(Palette.DIRT, random))
                pebbles(canvas, paint, random, Palette.DIRT_DARK, Palette.DIRT_LIGHT)
            }

            TileType.SAND -> {
                canvas.drawColor(jitter(Palette.SAND, random))
                pebbles(canvas, paint, random, Palette.SAND_DARK, Palette.SAND_LIGHT)
                paint.color = Palette.SAND_DARK
                canvas.drawRect(6f, 22f, 14f, 23f, paint)
            }

            TileType.WATER -> {
                canvas.drawColor(jitter(Palette.WATER, random))
                waves(canvas, paint, random, Palette.WATER_LIGHT, 2)
            }

            TileType.DEEP_WATER -> {
                canvas.drawColor(jitter(Palette.DEEP_WATER, random))
                waves(canvas, paint, random, Palette.DEEP_WATER_LIGHT, 1)
            }

            TileType.TREE, TileType.FOREST_TREE -> {
                // Match the ground the tree stands on: grass on plains, dark
                // forest floor inside forests.
                val base = if (type == TileType.TREE) Palette.GRASS else Palette.FOREST_FLOOR
                canvas.drawColor(jitter(base, random))
                tree(canvas, paint, random)
            }

            TileType.ROCK -> {
                canvas.drawColor(jitter(Palette.GRASS, random))
                rock(canvas, paint, random)
            }

            TileType.RUIN_FLOOR -> {
                canvas.drawColor(jitter(Palette.RUIN_FLOOR, random))
                ruinFloor(canvas, paint, random)
            }

            TileType.RUIN_WALL -> {
                canvas.drawColor(Palette.RUIN_MORTAR)
                ruinWall(canvas, paint, random)
            }
            TileType.SNOW -> {
                canvas.drawColor(jitter(0xFFD8EAF2.toInt(), random))
                pebbles(canvas, paint, random, 0xFFB7D3E3.toInt(), 0xFFF5FAFF.toInt())
            }
            TileType.ASH -> {
                canvas.drawColor(jitter(0xFF372B30.toInt(), random))
                pebbles(canvas, paint, random, 0xFF251F29.toInt(), 0xFF765044.toInt())
            }
            TileType.LAVA -> {
                canvas.drawColor(0xFF5A201C.toInt())
                paint.color = 0xFFFF7631.toInt()
                canvas.drawLine(0f, 10f + variant, 18f, 19f, paint)
                canvas.drawLine(18f, 19f, 32f, 6f + variant, paint)
                paint.color = 0xFFFFC35B.toInt()
                canvas.drawCircle(18f, 19f, 2.5f, paint)
            }
            TileType.ARENA_STONE -> {
                canvas.drawColor(jitter(0xFF8796A0.toInt(), random))
                paint.color = 0xFF526570.toInt()
                canvas.drawLine(0f, 16f, 32f, 16f, paint)
                canvas.drawLine(16f, 0f, 16f, 32f, paint)
                paint.color = 0xFFB8D4DB.toInt()
                canvas.drawCircle(16f, 16f, 2f, paint)
            }
        }
        return bitmap
    }

    private fun grassBlades(canvas: Canvas, paint: Paint, random: Random) {
        paint.color = Palette.GRASS_DARK
        for (i in 0 until 7) {
            val x = random.nextInt(TILE_PX - 2) + 1
            val y = random.nextInt(TILE_PX - 5) + 4
            canvas.drawRect(x.toFloat(), y.toFloat(), x + 1f, y + 3f, paint)
        }
        paint.color = Palette.GRASS_LIGHT
        for (i in 0 until 3) {
            val x = random.nextInt(TILE_PX - 2) + 1
            val y = random.nextInt(TILE_PX - 4) + 3
            canvas.drawRect(x.toFloat(), y.toFloat(), x + 2f, y + 1f, paint)
        }
    }

    private fun leafLitter(canvas: Canvas, paint: Paint, random: Random) {
        for (i in 0 until 6) {
            val x = random.nextInt(TILE_PX - 4) + 2
            val y = random.nextInt(TILE_PX - 4) + 2
            paint.color = if (i % 2 == 0) Palette.LEAF_BROWN else Palette.GRASS_DARK
            canvas.drawRect(x.toFloat(), y.toFloat(), x + 3f, y + 2f, paint)
        }
    }

    private fun flowers(canvas: Canvas, paint: Paint, random: Random) {
        val petals = intArrayOf(Palette.FLOWER_YELLOW, Palette.FLOWER_WHITE, Palette.FLOWER_PINK)
        for (i in 0 until 3) {
            val x = random.nextInt(TILE_PX - 8) + 4
            val y = random.nextInt(TILE_PX - 8) + 5
            paint.color = Palette.GRASS_DARK
            canvas.drawRect(x.toFloat(), y + 2f, x + 1f, y + 5f, paint)
            paint.color = petals[i % petals.size]
            canvas.drawRect(x - 1f, y.toFloat(), x + 2f, y + 2f, paint)
        }
    }

    private fun pebbles(canvas: Canvas, paint: Paint, random: Random, dark: Int, light: Int) {
        for (i in 0 until 5) {
            val x = random.nextInt(TILE_PX - 5) + 2
            val y = random.nextInt(TILE_PX - 5) + 2
            paint.color = if (i % 3 == 0) light else dark
            canvas.drawRect(x.toFloat(), y.toFloat(), x + 3f, y + 2f, paint)
        }
    }

    private fun waves(canvas: Canvas, paint: Paint, random: Random, color: Int, count: Int) {
        paint.color = color
        for (i in 0 until count) {
            val y = 6 + i * 12 + random.nextInt(4)
            val x = random.nextInt(8)
            canvas.drawRect(x.toFloat(), y.toFloat(), x + 18f, y + 2f, paint)
            canvas.drawRect(x + 22f, y.toFloat(), x + 30f, y + 2f, paint)
        }
    }

    private fun tree(canvas: Canvas, paint: Paint, random: Random) {
        paint.color = Palette.TRUNK
        canvas.drawRect(14f, 21f, 18f, 31f, paint)

        paint.color = Palette.TREE_DARK
        canvas.drawCircle(16f, 14f, 11f, paint)
        paint.color = Palette.TREE_MID
        canvas.drawCircle(12f, 15f, 7f, paint)
        canvas.drawCircle(21f, 16f, 6f, paint)
        paint.color = Palette.TREE_LIGHT
        canvas.drawCircle(13f, 11f, 4f, paint)
        canvas.drawRect(19f + random.nextInt(2).toFloat(), 9f, 22f, 11f, paint)
    }

    private fun rock(canvas: Canvas, paint: Paint, random: Random) {
        val path = Path()
        path.moveTo(7f, 27f)
        path.lineTo(5f, 18f)
        path.lineTo(10f, 9f)
        path.lineTo(20f, 6f)
        path.lineTo(27f, 13f)
        path.lineTo(26f, 27f)
        path.close()
        paint.color = Palette.ROCK
        canvas.drawPath(path, paint)

        paint.color = Palette.ROCK_LIGHT
        val highlight = Path()
        highlight.moveTo(10f, 10f)
        highlight.lineTo(19f, 7f)
        highlight.lineTo(22f, 11f)
        highlight.lineTo(11f, 14f)
        highlight.close()
        canvas.drawPath(highlight, paint)

        paint.color = Palette.ROCK_DARK
        canvas.drawRect(8f, 24f, 24f, 27f, paint)
        canvas.drawRect(
            22f + random.nextInt(2).toFloat(), 15f, 25f, 23f, paint,
        )
    }

    private fun ruinFloor(canvas: Canvas, paint: Paint, random: Random) {
        paint.color = Palette.RUIN_LINE
        canvas.drawRect(1f, 15f, 31f, 16f, paint)
        canvas.drawRect(15f, 1f, 16f, 31f, paint)
        paint.color = Palette.RUIN_MOSS
        canvas.drawRect(4f + random.nextInt(4).toFloat(), 20f, 9f, 23f, paint)
        paint.color = Palette.RUIN_LINE
        canvas.drawRect(20f, 5f, 24f, 6f, paint)
    }

    private fun ruinWall(canvas: Canvas, paint: Paint, random: Random) {
        paint.color = Palette.RUIN_BRICK
        var row = 0
        var y = 1
        while (y < TILE_PX) {
            val offset = if (row % 2 == 0) 0f else 8f
            var x = -offset
            while (x < TILE_PX) {
                val left = x + 1.5f
                val right = x + 14.5f
                if (right > 0f) {
                    canvas.drawRect(left.coerceAtLeast(0f), y.toFloat(), right, y + 6f, paint)
                }
                x += 16f
            }
            paint.color = if (random.nextBoolean()) Palette.RUIN_BRICK else Palette.RUIN_BRICK_DARK
            y += 8
            row++
        }
    }

    private fun jitter(color: Int, random: Random, amount: Float = 0.012f): Int {
        val factor = 1f + (random.nextFloat() * 2f - 1f) * amount
        return scale(color, factor)
    }

    private fun scale(color: Int, factor: Float): Int {
        val r = (((color shr 16) and 0xFF) * factor).toInt().coerceIn(0, 255)
        val g = (((color shr 8) and 0xFF) * factor).toInt().coerceIn(0, 255)
        val b = ((color and 0xFF) * factor).toInt().coerceIn(0, 255)
        return Color.rgb(r, g, b)
    }

    private object Palette {
        val GRASS = 0xFF4E7A3B.toInt()
        val GRASS_DARK = 0xFF3E6430.toInt()
        val GRASS_LIGHT = 0xFF5F8C48.toInt()

        val FOREST_FLOOR = 0xFF41643A.toInt()
        val LEAF_BROWN = 0xFF5C4A2E.toInt()

        val DIRT = 0xFF7A6142.toInt()
        val DIRT_DARK = 0xFF675034.toInt()
        val DIRT_LIGHT = 0xFF8C7252.toInt()

        val SAND = 0xFFC8B27C.toInt()
        val SAND_DARK = 0xFFB29A67.toInt()
        val SAND_LIGHT = 0xFFD8C590.toInt()

        val WATER = 0xFF2C5A78.toInt()
        val WATER_LIGHT = 0x559FC7D8
        val DEEP_WATER = 0xFF1E4157.toInt()
        val DEEP_WATER_LIGHT = 0x3A86AEC2

        val TRUNK = 0xFF4A3524.toInt()
        val TREE_DARK = 0xFF2A5228.toInt()
        val TREE_MID = 0xFF356433.toInt()
        val TREE_LIGHT = 0xFF437A3F.toInt()

        val ROCK = 0xFF6C6C74.toInt()
        val ROCK_LIGHT = 0xFF8B8B93.toInt()
        val ROCK_DARK = 0xFF4C4C54.toInt()

        val RUIN_FLOOR = 0xFF565660.toInt()
        val RUIN_LINE = 0xFF484852.toInt()
        val RUIN_MOSS = 0xFF4C5F45.toInt()
        val RUIN_MORTAR = 0xFF31313A.toInt()
        val RUIN_BRICK = 0xFF44444F.toInt()
        val RUIN_BRICK_DARK = 0xFF3C3C47.toInt()

        val FLOWER_YELLOW = 0xFFE8C85A.toInt()
        val FLOWER_WHITE = 0xFFEDE7D6.toInt()
        val FLOWER_PINK = 0xFFD98BA0.toInt()
    }
}
